<?php

declare(strict_types=1);

/**
 * FILE PURPOSE: Page view for Admin Custom Request Detail; it turns prepared application data into HTML.
 *
 * DATA FLOW: An HTTP entry point loads a bootstrap, obtains data from a controller, selects this file as $contentView, and loads a layout. Layout variables such as $escape are therefore injected into this view scope.
 */

use App\Services\CustomRequestService;

$humanize = static fn (mixed $value): string => ucwords(strtolower(str_replace('_', ' ', (string) $value)));
$format = static fn (mixed $value): string => is_string($value) && trim($value) !== '' ? $value : 'Not specified';
?>
<?php if (!is_array($requestDetail)): ?>
  <?php $emptyTitle = $requestResult['httpStatus'] === 404 ? 'Request not found' : 'Request unavailable'; $emptyMessage = 'Return to the request inbox and choose an available record.'; require __DIR__ . '/../../Components/Admin/empty-state.php'; ?>
<?php else: $request = $requestDetail['request']; ?>
  <header class="admin-page-header admin-page-header--detail"><div><p class="admin-eyebrow">Custom request</p><h1><?php echo $escape($request['request_number']); ?></h1><p class="admin-page-header__summary">Submitted <?php echo $escape((string) $request['created_at']); ?> · <?php echo $escape($request['category_name']); ?></p></div><div class="admin-detail-actions"><a class="admin-button admin-button--secondary" href="<?php echo $escape($backUrl); ?>">Back to inbox</a><?php if ((string) $request['request_status'] === 'AGREED' && $request['converted_order_id'] === null): ?><a class="admin-button" href="<?php echo BASE_URL . 'admin/requests/convert.php?id=' . $escape($request['id']); ?>">Create manual order</a><?php endif; ?></div></header>

  <?php if (is_string($noticeFlash['success'])): ?><?php $alertTone = 'success'; $alertTitle = 'Request updated'; $alertMessage = $noticeFlash['success']; require __DIR__ . '/../../Components/Admin/alert.php'; ?><?php endif; ?>
  <?php if ($actionFlash['errors'] !== []): ?><?php $alertTone = 'error'; $alertTitle = 'Update not saved'; $alertMessage = implode(' ', array_values($actionFlash['errors'])); require __DIR__ . '/../../Components/Admin/alert.php'; ?><?php endif; ?>

  <div class="admin-detail-grid admin-request-detail-grid">
    <div class="admin-detail-grid__main">
      <section class="admin-panel"><header class="admin-panel__header"><div><p class="admin-eyebrow">Submitted brief</p><h2>Preferences</h2></div><span class="admin-badge admin-badge--<?php echo $escape($request['attention']['tone']); ?>"><?php echo $escape($request['attention']['label']); ?></span></header>
        <dl class="admin-definition-grid"><div><dt>Product</dt><dd><?php echo $escape($format($request['product_name'])); ?></dd></div><div><dt>Quantity</dt><dd><?php echo $escape($format($request['requested_quantity'])); ?></dd></div><div><dt>Budget</dt><dd><?php echo $request['budget'] === null ? 'Not specified' : $escape(number_format((float) $request['budget'], 3)) . ' TND'; ?></dd></div><div><dt>Required date</dt><dd><?php echo $escape($format($request['required_date'])); ?></dd></div><div><dt>Color</dt><dd class="admin-long-copy"><?php echo nl2br($escape($format($request['color_preferences']))); ?></dd></div><div><dt>Scent</dt><dd class="admin-long-copy"><?php echo nl2br($escape($format($request['scent_preferences']))); ?></dd></div><div><dt>Packaging</dt><dd class="admin-long-copy"><?php echo nl2br($escape($format($request['packaging_preferences']))); ?></dd></div></dl>
        <div class="admin-message-block"><h3>Customer message</h3><p class="admin-long-copy"><?php echo nl2br($escape($format($request['customer_message']))); ?></p></div>
      </section>

      <section class="admin-panel"><header class="admin-panel__header"><div><h2>Contact history</h2></div></header>
        <?php if ($requestDetail['contacts'] === []): ?><?php $emptyTitle = 'No contact recorded'; $emptyMessage = 'Log operational contact attempts here without changing the customer’s submitted message.'; require __DIR__ . '/../../Components/Admin/empty-state.php'; ?>
        <?php else: ?><ol class="admin-timeline"><?php foreach ($requestDetail['contacts'] as $contact): ?><li><div><strong><?php echo $escape($humanize($contact['contact_outcome'])); ?></strong><span><?php echo $escape($humanize($contact['contact_method'])); ?> · <?php echo $escape($contact['administrator_name']); ?></span></div><time><?php echo $escape($contact['contacted_at']); ?></time><?php if ($contact['contact_notes'] !== null): ?><p class="admin-long-copy"><?php echo nl2br($escape($contact['contact_notes'])); ?></p><?php endif; ?><?php if ($contact['next_follow_up_at'] !== null): ?><small>Follow up: <?php echo $escape($contact['next_follow_up_at']); ?></small><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?>
      </section>
    </div>

    <aside class="admin-detail-grid__aside">
      <section class="admin-panel"><header class="admin-panel__header"><div><h2>Current state</h2></div></header><p><?php $status = $request['request_status']; require __DIR__ . '/../../Components/Admin/status-badge.php'; ?></p><dl class="admin-definition-list"><div><dt>Assigned</dt><dd><?php echo $escape($request['administrator_name'] ?? 'Unassigned'); ?></dd></div><?php if ($request['converted_order_id'] !== null): ?><div><dt>Order</dt><dd><a href="<?php echo BASE_URL . 'admin/orders/detail.php?id=' . $escape($request['converted_order_id']); ?>"><?php echo $escape($request['converted_order_number']); ?></a></dd></div><div><dt>Converted</dt><dd><?php echo $escape($request['converted_at']); ?></dd></div><?php endif; ?></dl></section>

      <section class="admin-panel admin-contact-card"><header class="admin-panel__header"><div><h2>Customer</h2></div></header><dl class="admin-definition-list"><div><dt>Name</dt><dd><?php echo $escape($request['customer_name_snapshot']); ?></dd></div><div><dt>Phone</dt><dd><?php echo $escape($request['customer_phone_snapshot']); ?></dd></div><div><dt>Email</dt><dd><?php echo $escape($format($request['customer_email_snapshot'])); ?></dd></div><div><dt>Preferred</dt><dd><?php echo $escape($humanize($request['preferred_contact_method'])); ?></dd></div></dl></section>

      <?php if ($requestDetail['editable']): ?>
        <section class="admin-panel"><h2>Assignment</h2><form class="admin-stack-form" action="<?php echo BASE_URL . 'admin/requests/action.php'; ?>" method="post"><input type="hidden" name="csrf_token" value="<?php echo $escape($csrf->token()); ?>"><input type="hidden" name="id" value="<?php echo $escape($request['id']); ?>"><input type="hidden" name="action" value="assign"><div class="admin-field"><label for="assigned-admin">Administrator</label><select id="assigned-admin" name="administrator_id"><option value="">Unassigned</option><?php foreach ($requestDetail['administrators'] as $admin): ?><option value="<?php echo $escape($admin['id']); ?>"<?php echo (string) $request['assigned_administrator_id'] === (string) $admin['id'] ? ' selected' : ''; ?>><?php echo $escape($admin['name']); ?></option><?php endforeach; ?></select></div><button class="admin-button admin-button--secondary" type="submit">Save assignment</button></form></section>

        <section class="admin-panel"><h2>Log contact</h2><form class="admin-stack-form" action="<?php echo BASE_URL . 'admin/requests/action.php'; ?>" method="post"><input type="hidden" name="csrf_token" value="<?php echo $escape($csrf->token()); ?>"><input type="hidden" name="id" value="<?php echo $escape($request['id']); ?>"><input type="hidden" name="action" value="contact"><div class="admin-field"><label for="contact-method">Method</label><select id="contact-method" name="contact_method" required><?php foreach (CustomRequestService::CONTACT_METHODS as $option): ?><option value="<?php echo $escape($option); ?>"<?php echo $request['preferred_contact_method'] === $option ? ' selected' : ''; ?>><?php echo $escape($humanize($option)); ?></option><?php endforeach; ?></select></div><div class="admin-field"><label for="contact-outcome">Outcome</label><select id="contact-outcome" name="contact_outcome" required><?php foreach (CustomRequestService::CONTACT_OUTCOMES as $option): ?><option value="<?php echo $escape($option); ?>"><?php echo $escape($humanize($option)); ?></option><?php endforeach; ?></select></div><div class="admin-field"><label for="contact-follow-up">Next follow-up (optional)</label><input id="contact-follow-up" name="follow_up" type="datetime-local"></div><div class="admin-field"><label for="contact-notes">Protected notes</label><textarea id="contact-notes" name="notes" maxlength="5000" rows="4"></textarea></div><button class="admin-button admin-button--secondary" type="submit">Record contact</button></form></section>

        <?php if ($requestDetail['allowedTransitions'] !== []): ?><section class="admin-panel"><h2>Change status</h2><form class="admin-stack-form" action="<?php echo BASE_URL . 'admin/requests/action.php'; ?>" method="post"><input type="hidden" name="csrf_token" value="<?php echo $escape($csrf->token()); ?>"><input type="hidden" name="id" value="<?php echo $escape($request['id']); ?>"><input type="hidden" name="action" value="transition"><div class="admin-field"><label for="new-request-status">Next status</label><select id="new-request-status" name="new_status" required><?php foreach ($requestDetail['allowedTransitions'] as $option): ?><option value="<?php echo $escape($option); ?>"><?php echo $escape($humanize($option)); ?></option><?php endforeach; ?></select></div><div class="admin-field"><label for="transition-method">Contact method (unless cancelled)</label><select id="transition-method" name="contact_method"><option value="">Not applicable</option><?php foreach (CustomRequestService::CONTACT_METHODS as $option): ?><option value="<?php echo $escape($option); ?>"<?php echo $request['preferred_contact_method'] === $option ? ' selected' : ''; ?>><?php echo $escape($humanize($option)); ?></option><?php endforeach; ?></select></div><div class="admin-field"><label for="transition-notes">Contact notes</label><textarea id="transition-notes" name="notes" maxlength="5000" rows="3"></textarea></div><button class="admin-button" type="submit">Update status</button></form></section><?php endif; ?>
      <?php else: ?><section class="admin-panel"><h2>Editing closed</h2><p>This request is terminal. Its assignment, status, and contact history are read-only.</p></section><?php endif; ?>
    </aside>
  </div>
<?php endif; ?>
